"""Cross-Field (CF) Consistency fix via majority voting for Event Extraction outputs.

For each document, collects all mentions of the same entity text across
events.arguments and entities list. When the same entity has inconsistent
entity_types (CF violation), applies majority voting to unify them.

Input:  JSONL with parsed_output per document (WikiEvents constrained format)
Output: Fixed JSONL + stdout statistics

Dependencies: Python 3.10+ (stdlib only)
"""

import argparse
import json
import copy
from collections import Counter, defaultdict
from pathlib import Path


def load_constraints(path: str) -> dict:
    """Load ontology constraints and normalize to argument_constraints format."""
    with open(path) as f:
        raw = json.load(f)
    if "argument_constraints" not in raw and "event_constraints" in raw:
        argument_constraints = {}
        for evt_type, evt_data in raw["event_constraints"].items():
            argument_constraints[evt_type] = evt_data.get("role_entity_constraints", {})
        raw["argument_constraints"] = argument_constraints
    return raw


def get_entity_type(obj: dict, source: str) -> str:
    """Extract entity_type from an entity or argument dict."""
    if source == "entity_list":
        return obj.get("entity_type", obj.get("type", "")).strip()
    return obj.get("entity_type", "").strip()


def set_entity_type(obj: dict, new_type: str, source: str):
    """Set entity_type on an entity or argument dict, preserving the original key."""
    if source == "entity_list":
        if "entity_type" in obj:
            obj["entity_type"] = new_type
        elif "type" in obj:
            obj["type"] = new_type
        else:
            obj["entity_type"] = new_type
    else:
        obj["entity_type"] = new_type


def collect_mentions(parsed: dict) -> dict[str, list[dict]]:
    """Collect all entity mentions grouped by lowercased text.

    Returns: {lower_text: [{"type": str, "source": "entity_list"|"argument",
                            "event_type": str|None, "role": str|None, "ref": dict}]}
    """
    mentions = defaultdict(list)

    for ent in parsed.get("entities", []):
        text = ent.get("text", "").strip()
        etype = get_entity_type(ent, "entity_list")
        if text and etype:
            mentions[text.lower()].append({
                "type": etype,
                "source": "entity_list",
                "event_type": None,
                "role": None,
                "ref": ent,
            })

    for event in parsed.get("events", []):
        evt_type = event.get("event_type", "")
        for arg in event.get("arguments", []):
            text = arg.get("text", "").strip()
            etype = get_entity_type(arg, "argument")
            if text and etype:
                mentions[text.lower()].append({
                    "type": etype,
                    "source": "argument",
                    "event_type": evt_type,
                    "role": arg.get("role", ""),
                    "ref": arg,
                })

    return mentions


def majority_vote(mention_list: list[dict]) -> str | None:
    """Pick majority entity_type. Tie-break: prefer type from entities list."""
    type_counts = Counter(m["type"] for m in mention_list)
    if len(type_counts) <= 1:
        return None

    max_count = max(type_counts.values())
    candidates = [t for t, c in type_counts.items() if c == max_count]

    if len(candidates) == 1:
        return candidates[0]

    entity_list_types = [m["type"] for m in mention_list if m["source"] == "entity_list"]
    if entity_list_types:
        el_counts = Counter(entity_list_types)
        for t in candidates:
            if t in el_counts:
                return t

    return candidates[0]


def is_ac_valid(event_type: str, role: str, entity_type: str,
                argument_constraints: dict) -> bool:
    """Check if entity_type is valid for (event_type, role) per AC constraints."""
    role_constraints = argument_constraints.get(event_type, {})
    valid_types = role_constraints.get(role)
    if valid_types is None:
        return True
    return entity_type in valid_types


def fix_document(parsed: dict, argument_constraints: dict) -> dict:
    """Apply majority voting CF fix to one document.

    Returns: {"corrections": [...], "ac_blocked": [...], "cf_before": int, "cf_after": int}
    """
    mentions = collect_mentions(parsed)

    corrections = []
    ac_blocked = []
    cf_before = 0
    cf_after = 0

    for text_lower, mlist in mentions.items():
        types_present = set(m["type"] for m in mlist)
        if len(types_present) <= 1:
            continue

        cf_before += 1
        winner = majority_vote(mlist)

        still_inconsistent = False
        for m in mlist:
            if m["type"] == winner:
                continue

            old_type = m["type"]
            if m["source"] == "argument" and m["event_type"] and m["role"]:
                if not is_ac_valid(m["event_type"], m["role"], winner, argument_constraints):
                    ac_blocked.append({
                        "text": text_lower,
                        "old_type": old_type,
                        "wanted_type": winner,
                        "event_type": m["event_type"],
                        "role": m["role"],
                    })
                    still_inconsistent = True
                    continue

            set_entity_type(m["ref"], winner, m["source"])
            corrections.append({
                "text": text_lower,
                "old_type": old_type,
                "new_type": winner,
                "source": m["source"],
            })

        if still_inconsistent:
            remaining_types = set()
            for m in mlist:
                remaining_types.add(get_entity_type(m["ref"], m["source"]))
            if len(remaining_types) > 1:
                cf_after += 1

    return {
        "corrections": corrections,
        "ac_blocked": ac_blocked,
        "cf_before": cf_before,
        "cf_after": cf_after,
    }


def main():
    parser = argparse.ArgumentParser(
        description="Fix CF violations via majority voting on entity_type"
    )
    parser.add_argument("--input_path", type=str, required=True,
                        help="Input JSONL with parsed_output per document")
    parser.add_argument("--output_path", type=str, required=True,
                        help="Output JSONL with corrected entity_types")
    parser.add_argument("--constraints_path", type=str, required=True,
                        help="Ontology constraints JSON for AC validation")
    args = parser.parse_args()

    constraints = load_constraints(args.constraints_path)
    argument_constraints = constraints.get("argument_constraints", {})

    records = []
    with open(args.input_path) as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    records.append(json.loads(line))
                except json.JSONDecodeError:
                    continue

    total_cf_before = 0
    total_cf_after = 0
    total_corrections = 0
    total_ac_blocked = 0
    correction_patterns = Counter()
    ac_blocked_details = []

    for rec in records:
        parsed = rec.get("parsed_output")
        if parsed is None:
            continue
        if isinstance(parsed, list):
            parsed = {"events": parsed}
            rec["parsed_output"] = parsed

        result = fix_document(parsed, argument_constraints)

        total_cf_before += result["cf_before"]
        total_cf_after += result["cf_after"]
        total_corrections += len(result["corrections"])
        total_ac_blocked += len(result["ac_blocked"])

        for c in result["corrections"]:
            correction_patterns[f"{c['old_type']}→{c['new_type']}"] += 1

        ac_blocked_details.extend(result["ac_blocked"])

    Path(args.output_path).parent.mkdir(parents=True, exist_ok=True)
    with open(args.output_path, "w") as f:
        for rec in records:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    fix_rate = (
        (total_cf_before - total_cf_after) / total_cf_before * 100
        if total_cf_before > 0 else 0.0
    )

    print("=== CF Majority Voting Report ===")
    print(f"Documents:           {len(records)}")
    print(f"CF violations before: {total_cf_before}")
    print(f"CF violations after:  {total_cf_after}")
    print(f"Fix rate:            {fix_rate:.1f}%")
    print(f"Total corrections:   {total_corrections}")
    print(f"AC-blocked:          {total_ac_blocked}")
    print()

    if correction_patterns:
        print("Correction patterns:")
        for pattern, count in correction_patterns.most_common():
            print(f"  {pattern}: {count}")
        print()

    if ac_blocked_details:
        print("AC-blocked examples (up to 10):")
        for ab in ac_blocked_details[:10]:
            print(f"  '{ab['text']}': {ab['old_type']}→{ab['wanted_type']} "
                  f"blocked by ({ab['event_type']}, {ab['role']})")


if __name__ == "__main__":
    main()
PYEOF
